def place(block, n, anchors):
    # block: list of (line_or_None, text); anchors fixed by explicit index; others packed in order
    out=['']*n; i=0
    for idx,t in block:
        if idx is not None: i=idx
        assert i<n and out[i]=='', (i,t)
        out[i]=t; i+=1
    return out
